function smallestNumber(num, t) {
  // Exhaustive cross-check without the greedy digit formula: the fewest digits that cover what is
  // still missing come from trying every digit (memoised), every filler is built one digit at a time
  // (the smallest digit that still leaves a way to finish), and all candidates are compared numerically.
  const primes = [2, 3, 5, 7];
  const need = primes.map(p => { let e = 0; while (t % p === 0) { t /= p; e++; } return e; });
  if (t !== 1) return '-1'; // a product of digits has no prime factor above 7
  const cover = (rest, d) => rest.map((e, i) => { let x = d; while (e > 0 && x % primes[i] === 0) { x /= primes[i]; e--; } return e; });
  const fewest = new Map();
  const minDigits = rest => {
    if (rest.every(e => e === 0)) return 0;
    const key = rest.join();
    if (!fewest.has(key)) {
      let best = Infinity;
      for (let d = 2; d <= 9; d++) { const next = cover(rest, d); if (next.join() !== key) best = Math.min(best, 1 + minDigits(next)); }
      fewest.set(key, best);
    }
    return fewest.get(key);
  };
  const fill = (k, rest) => { let out = ''; while (k-- > 0) { let d = 1; while (minDigits(cover(rest, d)) > k) d++; out += d; rest = cover(rest, d); } return out; };
  const less = (a, b) => a.length !== b.length ? a.length < b.length : a < b;
  // A longer number always works; then try keeping num's first i digits and raising digit i.
  let len = num.length + 1;
  while (minDigits(need) > len) len++;
  let best = fill(len, need);
  let rest = need;
  for (let i = 0; i < num.length; i++) {
    for (let d = Number(num[i]) + 1; d <= 9; d++) {
      const after = cover(rest, d);
      if (minDigits(after) > num.length - i - 1) continue;
      const candidate = num.slice(0, i) + d + fill(num.length - i - 1, after);
      if (less(candidate, best)) best = candidate;
      break; // a larger digit here only gives larger candidates
    }
    if (num[i] === '0') return best; // no candidate may keep this zero
    rest = cover(rest, Number(num[i]));
  }
  return rest.every(e => e === 0) ? num : best;
}

