function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const primes = [2, 3, 5, 7];
  // A random product of at most `count` primes from 2, 3, 5 and 7 that stays within `limit`.
  const product = (count, limit) => {
    let value = 1;
    for (let k = 0; k < count; k++) {
      const p = primes[pick(4)];
      if (value * p <= limit) value *= p;
    }
    return value;
  };
  const style = pick(5);
  const digit = () => {
    if (style === 0) return pick(10);
    if (style === 1) return rand() < 0.85 ? 9 : pick(10);
    if (style === 2) return rand() < 0.85 ? 1 : pick(10);
    return 1 + pick(9);
  };
  const n = large ? 10000 - pick(200) : 2 + pick(4);
  let num = String(1 + pick(9));
  while (num.length < n) num += String(digit());
  const kind = pick(8);
  let t;
  if (kind === 0) t = 1;
  else if (kind === 1) t = [11, 13, 17, 19, 23][pick(5)] * product(large ? 40 : 3, large ? 1e12 : 100);
  else if (kind === 2 && !large) t = 1 + pick(60);
  else t = product(large ? 1 + pick(50) : 1 + pick(7), large ? 1e14 : 1e6);
  return [num, t];
}
